insert into public.service_lifecycles (id, name, description) values
  ('f0000000-0000-4000-8000-000000000010', 'Blueprint Kit Adoption', 'The service blueprint of this template itself — how a team discovers, adopts, maps with, and operates agentic service blueprinting. Replace it with your own service; until then it doubles as documentation.');
insert into public.phases (id, service_lifecycle_id, name, description, order_position) values
  ('f0000000-0000-4000-8000-000700010000', 'f0000000-0000-4000-8000-000000000010', 'Discover', 'The adopter finds the kit and decides it is worth an afternoon.', 1),
  ('f0000000-0000-4000-8000-000700020000', 'f0000000-0000-4000-8000-000000000010', 'Adopt', 'The kit goes from repository to running app on the adopter’s machine.', 2),
  ('f0000000-0000-4000-8000-000700030000', 'f0000000-0000-4000-8000-000000000010', 'Map', 'sb:map turns the adopter’s own service into a validated, imported blueprint.', 3),
  ('f0000000-0000-4000-8000-000700040000', 'f0000000-0000-4000-8000-000000000010', 'Operate', 'The blueprint stays true through audits, what-ifs, slices, and agent sessions — and loops back to Map when the service changes.', 4);
insert into public.service_scenarios (id, phase_id, name, description, order_position, view_type) values
  ('f0000000-0000-4000-8000-100000000001', 'f0000000-0000-4000-8000-000700010000', 'Discover the kit', 'A first visit: the repository pitch, the live example, the model figures, and the decision to try it.', 1, 'single'),
  ('f0000000-0000-4000-8000-200000000001', 'f0000000-0000-4000-8000-000700020000', 'Clone & first run', 'Two ways to a running app: the zero-config no-database run, and the same journey backed by a local Supabase stack.', 1, 'side-by-side'),
  ('f0000000-0000-4000-8000-300000000001', 'f0000000-0000-4000-8000-000700030000', 'Map your service', 'The sb:map pipeline: elicitation → draft → validation → adversarial review → per-scenario sign-off → import → deploy.', 1, 'single'),
  ('f0000000-0000-4000-8000-400000000001', 'f0000000-0000-4000-8000-000700040000', 'Review & present', 'sb:slice takes one stakeholder view out of the blueprint and carries it into presentation mode and PDF.', 1, 'single'),
  ('f0000000-0000-4000-8000-500000000001', 'f0000000-0000-4000-8000-000700040000', 'Keep it true', 'The stewardship loop: sb:audit finds drift, sb:whatif traces the fix, the re-import lands it — then the loop runs again.', 2, 'single');
insert into public.paths (id, service_scenario_id, name, description, note, path_type) values
  ('f0000000-0000-4000-8000-110000000000', 'f0000000-0000-4000-8000-100000000001', 'First visit', 'Reading the repo end to end, from pitch to decision.', null, 'happy'),
  ('f0000000-0000-4000-8000-210000000000', 'f0000000-0000-4000-8000-200000000001', 'No-database run', 'Zero config: clone, install, run — the bundled sample content renders with no environment at all.', null, 'happy'),
  ('f0000000-0000-4000-8000-220000000000', 'f0000000-0000-4000-8000-200000000001', 'Supabase run', 'The same first run backed by a local Supabase stack: migrations, seed, and live reads through the anon key.', null, 'alternative'),
  ('f0000000-0000-4000-8000-310000000000', 'f0000000-0000-4000-8000-300000000001', 'Guided mapping', 'A full pass from “map our service” to a deployed blueprint, every phase ending at a deterministic gate.', null, 'happy'),
  ('f0000000-0000-4000-8000-410000000000', 'f0000000-0000-4000-8000-400000000001', 'Stakeholder readout', 'From “show me my part” to a presented, exportable slice that still points at its cells.', null, 'happy'),
  ('f0000000-0000-4000-8000-510000000000', 'f0000000-0000-4000-8000-500000000001', 'Stewardship loop', 'Audit finding → traced fix → re-import → re-audit; agent sessions answer from the result.', null, 'happy');
